import sys
from functools import cmp_to_key

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0].strip())
    persons = []
    for i in range(1, n + 1):
        if i >= len(data):
            break
        parts = data[i].split()
        if len(parts) < 2:
            continue
        name = parts[0]
        age = int(parts[1])
        persons.append(Person(name, age))

    persons.sort(key=cmp_to_key(
        lambda a, b: (b.age - a.age) or (-1 if a.name < b.name else (1 if a.name > b.name else 0))
    ))

    lines = [f"{p.name} {p.age}" for p in persons]
    if lines:
        sys.stdout.write("\n".join(lines) + "\n")

if __name__ == "__main__":
    main()
